candidates.raw:
    if ((requested == NULL) || (area_turns == NULL) || (resistance == NULL) || 
        (voltage_limit == NULL) || (voltage == NULL) || (realized == NULL) || (mask == NULL)) {
        voltage->x = 0.0; voltage->y = 0.0; voltage->z = 0.0;
        realized->x = 0.0; realized->y = 0.0; realized->z = 0.0;
        *mask = 0U;
        return ADCS_E_NULL;
    }

    size_t i;
    unint32 sat_mask = 0U;

    // Validate inputs: area_turns > 0, resistance > 0, voltage_limit >= 0
    for (i = 0; i < 3; i++) {
        double at, r, vl;
        switch(i) {
            case 0: at = area_turns[0]; r = resistance[0]; vl = voltage_limit[0]; break;
            case 1: at = area_turns[1]; r = resistance[1]; vl = voltage_limit[1]; break;
            case 2: at = area_turns[2]; r = resistance[2]; vl = voltage_limit[2]; break;
            default: continue;
        }

        if (!isfinite(at) || at <= 0.0 ||
            !isfinite(r) || r <= 0.0 ||
            !isfinite(vl) || vl < 0.0) {
            voltage->x = 0.0; voltage->y = 0.0; voltage->z = 0.0;
            realized->x = 0.0; realized->y = 0.0; realized->z = 0.0;
            *mask = 0U;
            return ADCS_E_RANGE;
        }
    }

    // Process each coil
    for (i = 0; i < 3; i++) {
        double req_val, at, r, vl, raw_voltage, limited_voltage, realized_dipole;
        int clipped = 0;

        switch(i) {
            case 0:
                req_val = requested->x;
                at = area_turns[0];
                r = resistance[0];
                vl = voltage_limit[0];
                break;
            case 1:
                req_val = requested->y;
                at = area_turns[1];
                r = resistance[1];
                vl = voltage_limit[1];
                break;
            case 2:
                req_val = requested->z;
                at = area_turns[2];
                r = resistance[2];
                vl = voltage_limit[2];
                break;
            default:
                continue;
        }

        // Calculate raw voltage: resistance * requested / area_turns
        raw_voltage = r * req_val / at;

        // Bound checking: +/- voltage_limit
        if (raw_voltage > vl) {
            limited_voltage = vl;
            clipped = 1;
        } else if (raw_voltage < -vl) {
            limited_voltage = -vl;
            clipped = 1;
        } else {
            limited_voltage = raw_voltage;
        }

        // Set mask bit if clipped
        if (clipped) {
            sat_mask |= (1u << i);
        }

        // Calculate realized dipole: V_limited * area_turns / resistance
        realized_dipole = limited_voltage * at / r;

        // Store results into output vectors
        switch(i) {
            case 0:
                voltage->x = limited_voltage;
                realized->x = realized_dipole;
                break;
            case 1:
                voltage->y = limited_voltage;
                realized->y = realized_dipole;
                break;
            case 2:
                voltage->z = limited_voltage;
                realized->z = realized_dipole;
                break;
        }
    }

    *mask = sat_mask;
    return ADCS_OK;
}

